-- Liechtenstein: country row + name translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

-- roi_complexity and eu_member are written explicitly, never left to
-- the column defaults. 'none' would price the country at zero
-- integrations in the ROI planner and exempt it from the weekly
-- complexity review, which only scans countries rated 'simple'.
INSERT OR IGNORE INTO countries (code, name_en, region, slug, in_picker, roi_complexity, eu_member) VALUES ('LI', 'Liechtenstein', 'Europe', 'liechtenstein', 1, 'none', 0);

INSERT OR IGNORE INTO country_translations (country_id, lang, display_name) SELECT id, 'en', 'Liechtenstein' FROM countries WHERE code = 'LI';
INSERT OR IGNORE INTO country_translations (country_id, lang, display_name) SELECT id, 'es', 'Liechtenstein' FROM countries WHERE code = 'LI';
INSERT OR IGNORE INTO country_translations (country_id, lang, display_name) SELECT id, 'de', 'Liechtenstein' FROM countries WHERE code = 'LI';
INSERT OR IGNORE INTO country_translations (country_id, lang, display_name) SELECT id, 'fr', 'Liechtenstein' FROM countries WHERE code = 'LI';

-- ---- what this migration claims it did (see apply_migrations.py) ----
-- INSERT OR IGNORE cannot fail; it can only decline. Assert the row
-- and all four display names are actually there, so a code that
-- collides with an existing country is caught in replay rather than
-- discovered as a missing menu entry.
